(()=>{
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const defaults={day:1,coins:45,produce:3,water:80,food:78,thirst:82,well:92,panels:1,battery:1,inverter:1,voltage:12,series:1,pump:0,wellUpgrade:0,house:0,garden:0,animals:0,seeded:0,harvest:0,dayProgress:0,rotation:0,zoom:1,sound:true,visited:[],lastDay:Date.now()};
let s={...defaults,...JSON.parse(localStorage.getItem('hearthwild-save')||'{}')};let activeTab='today',toastTimer, renderer,scene,camera,worldGroup;
const seasons=['SPRING','SUMMER','AUTUMN','WINTER'],season=()=>seasons[Math.floor((s.day-1)/18)%4], seasonIndex=()=>seasons.indexOf(season());
const cropData={Radishes:{seasons:[0,1,2],days:2,water:12,seed:4,price:12,icon:'◉',info:'Quick-growing and cool-season friendly. Radishes are ready in just a couple of days.'},Beans:{seasons:[1,2],days:3,water:18,seed:7,price:20,icon:'⌁',info:'Beans love warm soil and add nitrogen back to the garden. Give them a little room to climb.'},Kale:{seasons:[0,2,3],days:4,water:16,seed:6,price:18,icon:'❋',info:'A hardy leafy green that handles cool weather. Mulch helps protect roots through a light frost.'},Tomatoes:{seasons:[1],days:4,water:24,seed:9,price:26,icon:'●',info:'Tomatoes need warm nights, steady moisture, and lots of sun. Avoid wetting leaves to limit disease.'}};
function save(){localStorage.setItem('hearthwild-save',JSON.stringify(s))}
function showToast(t){let el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function seasonCrop(){return Object.keys(cropData).filter(k=>cropData[k].seasons.includes(seasonIndex()))}
function notify(txt){showToast(txt)}
function doAction(type,arg){switch(type){case'water':if(s.water<10)return notify('Not enough water — haul some in or upgrade your collection.');s.water-=10;s.thirst=Math.min(100,s.thirst+25);s.well=Math.min(100,s.well+2);notify('A good drink. You feel more like yourself.');break;
case'eat':if(s.produce<1)return notify('No harvest to eat yet. Try gathering wild greens.');s.produce--;s.food=Math.min(100,s.food+30);s.well=Math.min(100,s.well+3);notify('A simple meal, grown by you.');break;
case'gather':s.food=Math.min(100,s.food+13);s.produce+=1;notify('Found wild berries and greens. Always identify plants first!');break;
case'plant':if(s.seeded)return notify('There is already a crop growing.');let c=arg||seasonCrop()[0];if(!c||!cropData[c])return;let d=cropData[c];if(!d.seasons.includes(seasonIndex()))return notify(`${c} prefers a different season.`);if(s.coins<d.seed)return notify('Not enough credits for those seeds.');if(s.water<d.water)return notify('Not enough water to plant that crop. Haul in water first.');s.coins-=d.seed;s.water-=d.water;s.seeded={crop:c,progress:0,watered:true};s.garden=Math.max(s.garden,1);notify(`${c} planted — keep it watered!`);break;
case'waterCrop':if(!s.seeded)return;if(s.water<8)return notify('You need 8 litres to water the garden.');s.water-=8;s.seeded.watered=true;notify('Garden watered. A little goes a long way.');break;
case'harvest':if(!s.seeded||s.seeded.progress<cropData[s.seeded.crop].days)return notify('Not ready yet. Give it time and water.');s.produce+=2+(s.pump?1:0);s.harvest++;s.seeded=null;notify('Harvest gathered! Two portions for your pantry.');break;
case'haul':if(s.coins<15)return notify('You need 15 credits for a water delivery.');s.coins-=15;s.water+=100;notify('Water delivery arrived: +100 litres.');break;
case'rest':s.well=Math.min(100,s.well+24);s.food=Math.max(0,s.food-5);s.thirst=Math.max(0,s.thirst-6);notify('A quiet rest restores your wellbeing.');break;
case'trade':if(s.produce<1)return notify('No harvest to sell yet.');s.produce--;s.coins+=cropData[s.lastCrop||'Radishes']?.price||12;notify('Produce sold at the local market. +12 credits');break;
case'feed':if(s.produce<1)return notify('You need one harvest to feed your chickens.');s.produce--;s.food=Math.min(100,s.food+15);s.coins+=7;notify('Eggs and a meal! The hens are earning their keep.');break;
case'buy':purchase(arg);break;
case'next':nextDay();break;
case'config':configSystem();return;
case'explore':if(s.well<15)return notify('Rest first; exploring while exhausted is risky.');s.coins+=12;s.water+=4;s.food=Math.max(0,s.food-7);s.well-=9;notify('A short walk found a nearby market: +12 credits.');break;
}update();}
const upgrades={panel:{name:'Solar panel',icon:'☼',desc:'More sunlight captured each day.',cost:40,cap:5,key:'panels',learn:'Solar panels are wired in series to raise voltage, or parallel to add current. Matching panel specs matters.'},battery:{name:'Battery bank',icon:'▰',desc:'Store extra energy for cloudy days.',cost:45,cap:5,key:'battery',learn:'Batteries store energy, not make it. Capacity (Wh) = voltage × amp-hours; avoid draining lead-acid below about 50%.'},inverter:{name:'Pure sine inverter',icon:'ϟ',desc:'Run more useful AC appliances.',cost:55,cap:4,key:'inverter',learn:'An inverter changes DC battery power to household AC. Size it for peak watts, and remember conversion losses.'},pump:{name:'Drip irrigation',icon:'⌁',desc:'Use less water, grow more food.',cost:50,cap:1,key:'pump',learn:'Drip irrigation delivers water at the roots and can use 30–50% less than overhead watering.'},wellUpgrade:{name:'Rain catchment',icon:'◉',desc:'Collect more from every rainfall.',cost:35,cap:3,key:'wellUpgrade',learn:'A 1 mm rain on 1 m² of roof yields about 1 litre before losses. Gutters and a covered tank make collection practical.'},house:{name:'Shelter upgrade',icon:'⌂',desc:'Trade canvas for a sturdier roof.',cost:60,cap:3,key:'house',learn:'Insulation reduces heating needs. Start with a dry, tight envelope, then add appropriately sized systems.'},garden:{name:'Garden beds',icon:'❋',desc:'Make room for another crop.',cost:35,cap:3,key:'garden',learn:'Rotate crop families and keep living roots in the soil when possible to support soil health.'},animals:{name:'A few hens',icon:'♧',desc:'Eggs, companionship, daily chores.',cost:75,cap:1,key:'animals',learn:'Chickens need secure night housing, clean water, feed, and daily care. They are a commitment, not a machine.'}};
function purchase(k){let u=upgrades[k];if(!u)return;let n=s[u.key];let cost=u.cost+(n*15);if(n>=u.cap)return notify('You have reached the current upgrade limit.');if(s.coins<cost)return notify(`You need ${cost} credits for this upgrade.`);if(k==='house'&&s.house===0&&s.panels<2)return notify('Add one more panel before building a bigger shelter.');s.coins-=cost;s[u.key]++;if(k==='house'&&s.house===1){$('#shelterLabel').lastChild.textContent='CABIN';}if(k==='panel'&&s.panels===2)s.voltage=24;if(k==='panel'&&s.panels===4)s.voltage=48;notify(`${u.name} upgraded!`);s.visited.push(u.learn);update();}
function nextDay(){s.day++;s.dayProgress=0;s.food=Math.max(0,s.food-8);s.thirst=Math.max(0,s.thirst-12);s.well=Math.max(0,s.well-2);if(seasonIndex()===3)s.well=Math.max(0,s.well-2);if(s.animals)s.food=Math.min(100,s.food+5);if(s.seeded){let crop=cropData[s.seeded.crop];if(s.seeded.watered){s.seeded.progress++;s.seeded.watered=false;}else{s.seeded.progress=Math.max(0,s.seeded.progress-1);notify('Your crop wilted a little without water.');}}let rain=Math.random()<(.25+s.wellUpgrade*.06);if(rain){s.water+=Math.round(8+s.wellUpgrade*8);showToast('Rain! Catchment added water to your tank.');}s.water=Math.min(250+s.wellUpgrade*100,s.water);if(s.day%3===0){s.coins+=5;showToast('A small homestead stipend: +5 credits.');}if(s.day%6===0){let weather=['Clear','Breezy','Cloudy','Rain'];$('#weatherLabel').textContent=weather[Math.floor(Math.random()*weather.length)];}s.lastDay=Date.now();update();}
function update(){let labels={dayNumber:`DAY ${String(s.day).padStart(2,'0')}`,seasonLabel:season(),foodVal:Math.round(s.food),thirstVal:Math.round(s.thirst),wellVal:Math.round(s.well),coinVal:s.coins,produceVal:s.produce,waterVal:s.water,weatherShort:season()==='WINTER'?'Cold · 4°':season()==='SUMMER'?'Warm · 27°':'Mild · 18°'};Object.entries(labels).forEach(([id,v])=>{if($('#'+id))$('#'+id).textContent=v});[['foodMeter',s.food],['thirstMeter',s.thirst],['wellMeter',s.well]].forEach(([id,v])=>$('#'+id).style.width=Math.max(0,Math.min(100,v))+'%');$('#dayProgress').style.width=(s.dayProgress||22)+'%';$('#weatherLabel').textContent=$('#weatherLabel').textContent||'Clear';$('#shelterLabel').lastChild.textContent=s.house>=3?'CABIN':s.house>=1?'SHELTER':'TENT';$('#captionText').textContent=s.house>=3?'A cabin, built one good decision at a time.':s.house?'A sturdier shelter, and room to dream.':'A quiet place to begin again.';$('#chapterLabel').textContent=s.house>=3?'CHAPTER THREE · ROOTED':'CHAPTER ONE · A PLACE TO LAND';$('#welcomeTitle').innerHTML=s.house>=3?'Rooted in the<br><em>wild.</em>':s.house?'Build a life<br><em>that fits.</em>':'Make this place<br><em>your own.</em>';if(activeTab==='today')renderToday();if(activeTab==='homestead')renderHomestead();if(activeTab==='fieldbook')renderNotes();save();if(worldGroup)updateScene();}
function renderToday(){let c=seasonCrop();let grow=s.seeded?`<div class="task"><div class="task-icon">${cropData[s.seeded.crop].icon}</div><div class="task-copy"><strong>${s.seeded.crop} · day ${s.seeded.progress}/${cropData[s.seeded.crop].days}</strong><small>${s.seeded.progress>=cropData[s.seeded.crop].days?'Ready to harvest!':s.seeded.watered?'Watered for today':'Needs 8 L of water'}</small></div><button class="task-action" data-action="${s.seeded.progress>=cropData[s.seeded.crop].days?'harvest':'waterCrop'}">${s.seeded.progress>=cropData[s.seeded.crop].days?'Harvest':s.seeded.watered?'Grow':'Water · 8 L'}</button></div>`:`<div class="task"><div class="task-icon">❋</div><div class="task-copy"><strong>Plant a seasonal crop</strong><small>${c.join(', ')} grow well right now</small></div><button class="task-action" data-action="plant" data-arg="${c[0]}">Plant · ${cropData[c[0]].seed} cr</button></div>`;
$('#content').innerHTML=`<div class="section-head"><span class="section-title">A good day starts small</span><span class="section-sub">${season().toLowerCase()} day ${s.day}</span></div><div class="weather-note"><span class="weather-ico">${season()==='WINTER'?'❄':'☀'}</span><div><strong>${season()} on the homestead</strong><p>${season()==='WINTER'?'Protect your water stores from freezing; kale can handle the chill.':season()==='SUMMER'?'Long sunny days are great for solar and warm-season crops. Water early to limit evaporation.':'A good time to plant cool-season crops and watch the forecast.'}</p></div></div><div class="section-head"><span class="section-title">Today’s little to-dos</span><span class="section-sub">one step at a time</span></div><div class="task-list"><div class="task"><div class="task-icon">◌</div><div class="task-copy"><strong>Drink some water</strong><small>${s.water} L in storage · stay ahead of thirst</small></div><button class="task-action" data-action="water">Drink</button></div><div class="task"><div class="task-icon">⌁</div><div class="task-copy"><strong>Make yourself a meal</strong><small>${s.produce} harvest portions in your pantry</small></div><button class="task-action" data-action="eat" ${s.produce<1?'disabled':''}>Cook</button></div>${grow}<div class="task"><div class="task-icon">☾</div><div class="task-copy"><strong>Take a breather</strong><small>Rest restores wellbeing, but takes a little daylight</small></div><button class="task-action" data-action="rest">Rest</button></div></div><div class="section-head gap"><span class="section-title">Your 12 V starter system</span><span class="section-sub">${s.voltage} V · DC</span></div><div class="energy-card"><div class="energy-head"><div class="energy-title"><i>ϟ</i> OFF-GRID POWER</div><span>${s.panels} panel${s.panels!==1?'s':''} · ${s.battery} battery</span></div><div class="energy-stats"><div class="energy-stat"><b>${s.panels*100} W</b><small>panel output</small></div><div class="energy-stat"><b>${s.voltage} V</b><small>system voltage</small></div><div class="energy-stat"><b>${s.battery*600} Wh</b><small>stored energy</small></div></div><div class="energy-bar"><span style="width:${Math.min(100,30+s.panels*12)}%"></span></div><div class="energy-foot"><span>Sunny day estimate</span><span>${s.panels*350} Wh/day ☀</span></div></div><div class="footer-tip">✦ &nbsp;${s.voltage===12?'At 12 V, a 1,000 W load draws ~83 A — short, thick cables matter.':'Higher voltage means less current for the same power; your wiring can be more efficient.'}</div><div class="task" style="margin-top:9px"><div class="task-icon">⌂</div><div class="task-copy"><strong>Take a little walk</strong><small>Find supplies and a few credits nearby</small></div><button class="task-action" data-action="explore">Explore</button></div><div class="task" style="margin-top:7px"><div class="task-icon">◷</div><div class="task-copy"><strong>Turn in for the night</strong><small>Tomorrow brings another chance</small></div><button class="task-action" data-action="next">End day →</button></div>`;}
function renderHomestead(){let keys=Object.keys(upgrades);$('#content').innerHTML=`<div class="section-head"><span class="section-title">Build your off-grid life</span><span class="section-sub">${s.coins} credits available</span></div><div class="system-card"><div class="system-top"><strong>⚡ Power system</strong><span class="system-pill">${s.voltage} V ${s.voltage===12?'starter':'system'}</span></div><div class="system-grid"><div><b>${s.panels} × 100 W</b><small>solar panels</small></div><div><b>${s.battery} × 600 Wh</b><small>battery bank</small></div><div><b>${s.inverter*300} W</b><small>inverter</small></div></div><button class="config-btn" data-action="config">Configure series / parallel ⟶</button></div><div class="upgrade-detail"><b>Power in plain language</b> · Series wiring adds voltage; parallel wiring adds current. Keep panel ratings compatible and use proper fuses. Your 12 V starter can grow to 24 V, then 48 V.</div><div class="section-head"><span class="section-title">Homestead upgrades</span><span class="section-sub">buy with credits</span></div><div class="upgrade-grid">${keys.map(k=>{let u=upgrades[k],n=s[u.key],cost=u.cost+n*15;return `<div class="upgrade-card"><div class="upgrade-icon">${u.icon}</div><h3>${u.name}</h3><p>${u.desc}${n?` · lvl ${n}`:''}</p><button class="upgrade-btn" data-action="buy" data-arg="${k}" ${n>=u.cap||s.coins<cost?'disabled':''}>${n>=u.cap?'Max level':`Upgrade · ${cost} cr`}</button></div>`}).join('')}</div><div class="section-head gap"><span class="section-title">A little more water</span><span class="section-sub">${s.water} L stored</span></div><div class="task"><div class="task-icon">◉</div><div class="task-copy"><strong>Haul in a 100 L delivery</strong><small>Reliable, costs 15 credits · rain is free but uncertain</small></div><button class="task-action" data-action="haul" ${s.coins<15?'disabled':''}>Order · 15 cr</button></div><div class="footer-tip">Water budget: garden crops need roughly 12–24 L through a short growing cycle; usage varies with weather and soil.</div>`;}
function renderNotes(){let cards=[['Electricity · your 12 V start','⟐',`Your system starts at 12 V with ${s.panels} × 100 W panel${s.panels!==1?'s':''}. A 12 V, 600 Wh battery stores about 50 Ah (600 ÷ 12), before losses. A real setup needs a charge controller, fuses, correctly sized wire, and safe installation.`],['Series or parallel?','⌁','Wire panels in <b>series</b> to add their voltages while current stays similar. Wire in <b>parallel</b> to keep voltage the same while currents add. Never exceed your charge controller’s voltage limit. Batteries must be matched and connected safely.'],['Water · every drop counts','◉','Plants need water to move nutrients and cool their leaves. A simple drip line puts water near roots. Mulch reduces evaporation. Rain capture depends on roof area and rainfall: litres ≈ rain (mm) × roof area (m²) × collection efficiency.'],['Seasonal growing','❋',`It is ${season().toLowerCase()}. ${seasonCrop().join(', ')} can grow now. Cool-weather crops like kale tolerate frost; tomatoes need warm nights. Local frost dates, sunlight, and your growing zone matter.`],['Living with animals','♧',s.animals?'Your hens need clean water, secure housing, balanced feed, and daily checks. Egg production changes with daylight and season.':'A few hens can provide eggs, but they need secure night housing, fresh water, balanced feed, and daily care. Plan the daily chores before you bring animals home.'],['Shelter & energy','⌂',`Your current shelter: <b>${s.house>=3?'cabin':s.house?'upgraded shelter':'tent'}</b>. Reduce energy needs first with shade, insulation, efficient appliances, and good habits. An inverter converts battery DC to household AC, but loses some energy as heat.`]];$('#content').innerHTML=`<div class="section-head"><span class="section-title">What the homestead is teaching</span><span class="section-sub">real-world notes</span></div>${cards.map(([h,i,p])=>`<div class="note-card"><div class="note-card-head"><span class="note-ico">${i}</span><strong>${h}</strong></div><p>${p}</p></div>`).join('')}<div class="upgrade-detail">These are simplified learning models, not installation instructions. Real electrical systems can cause fire or injury: consult local codes and a qualified professional.</div>`;}
function configSystem(){let max=s.panels;let body=`<p>Panel strings change the voltage and current delivered to a controller. Use only a configuration your equipment supports.</p><div class="modal-callout"><b>Your homestead:</b> ${s.panels} panels · ${s.voltage} V target · ${s.battery} battery bank<br>Series: <b>${s.series}</b> panel${s.series!==1?'s':''} per string · parallel strings: <b>${Math.max(1,Math.floor(s.panels/s.series))}</b></div><p><strong>Choose panels in series per string:</strong></p><div class="config-choices">${[1,2,4].filter(n=>n<=Math.max(1,max)).map(n=>`<button class="task-action config-choice" data-series="${n}" style="margin:0 6px 6px 0" ${n===s.series?'disabled':''}>${n} in series${n===s.series?' · selected':''}</button>`).join('')}</div><p>More series panels raise array voltage; more parallel strings increase current. The controller must be rated for the array’s open-circuit voltage and current.</p><div class="modal-callout">${s.panels>=4?'48 V is available with four panels in series.':s.panels>=2?'24 V is available with two panels in series. Add panels to unlock 48 V.':'Add panels before increasing your system voltage.'}</div>`;openModal('A tidy little power system',body);$$('.config-choice').forEach(b=>b.onclick=()=>{let n=+b.dataset.series;s.series=n;s.voltage=n>=4?48:n>=2?24:12;notify(`${n} panel${n===1?'':'s'} in series · ${s.voltage} V`);closeModal();update();});}

function openModal(title,html){$('#modalTitle').innerHTML=title;$('#modalBody').innerHTML=`<div class="modal-copy">${html}</div>`;$('#modal').classList.add('open')};function closeModal(){$('#modal').classList.remove('open')}
function showGuide(){openModal('Small choices.<br><em>Real know-how.</em>',`<p>Welcome to your little corner of the wild. Keep an eye on hunger, thirst, and wellbeing; tend a garden; and grow your homestead one upgrade at a time.</p><div class="modal-callout"><strong>Your first day:</strong> drink water, gather a little food, plant a seasonal crop, then end the day. Crops grow between days when watered.</div><p><strong>Power:</strong> Start at 12 V. Add solar panels, batteries, and an inverter. Panel strings can be wired in series or parallel; configure them in Homestead. Four panels unlock the 48 V path.</p><p><strong>Water:</strong> Rain catchment is useful but uncertain. You can always pay to haul in water. Drip irrigation helps crops use less.</p><p>Tap <strong>Field Notes</strong> for real-world facts. This game simplifies a complex subject; actual electrical installations should follow local codes and be designed safely.</p>`)}
function updateScene(){if(!worldGroup)return;let cabin=worldGroup.getObjectByName('cabin');if(cabin)cabin.visible=s.house>0;let solar=worldGroup.getObjectByName('solar');if(solar){solar.children.forEach((c,i)=>c.visible=i<s.panels)}let beds=worldGroup.getObjectByName('beds');if(beds){beds.children.forEach((c,i)=>c.visible=i<Math.max(1,s.garden+1));}let hen=worldGroup.getObjectByName('hen');if(hen)hen.visible=!!s.animals;let tank=worldGroup.getObjectByName('tank');if(tank) tank.scale.y=0.55+(s.water/250)*.5;}
function initScene(){let canvas=$('#scene');if(!window.THREE){canvas.style.background='linear-gradient(#abcbbf 0 46%,#829d79 46%)';return}try{renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,2));renderer.outputEncoding=THREE.sRGBEncoding;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.setClearColor(0xa9c5b4);scene=new THREE.Scene();scene.background=new THREE.Color(0xa9c5b4);scene.fog=new THREE.Fog(0xa9c5b4,21,40);camera=new THREE.PerspectiveCamera(35,1,.1,100);camera.position.set(12,11,15);camera.lookAt(0,0,0);worldGroup=new THREE.Group();scene.add(worldGroup);
const mat=(color,rough=.85)=>new THREE.MeshStandardMaterial({color,roughness:rough});const groundMat=mat(0x819976),pathMat=mat(0xc6b798),wood=mat(0x9c7657),cream=mat(0xe2d6b7),roof=mat(0x647962),leaf=mat(0x567c51),leaf2=mat(0x83a96e),dark=mat(0x3d5143),blue=mat(0x5d8790),solarMat=new THREE.MeshStandardMaterial({color:0x314d5b,metalness:.45,roughness:.35}),flower=mat(0xf0d18a),stone=mat(0xaaa99a);
const add=(geo,m,x,y,z,group=worldGroup)=>{let o=new THREE.Mesh(geo,m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;group.add(o);return o};const box=(x,y,z,m,a,b,c,group=worldGroup)=>add(new THREE.BoxGeometry(a,b,c),m,x,y,z,group);const cyl=(x,y,z,m,rt,rb,h,group=worldGroup,n=9)=>add(new THREE.CylinderGeometry(rt,rb,h,n),m,x,y,z,group);
let hemi=new THREE.HemisphereLight(0xe4f0e2,0x596550,2.1);scene.add(hemi);let sun=new THREE.DirectionalLight(0xffe6bc,2.2);sun.position.set(-7,12,8);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-13;sun.shadow.camera.right=13;sun.shadow.camera.top=13;sun.shadow.camera.bottom=-13;scene.add(sun);
box(0,-.28,0,groundMat,24,.5,20);let terrain=new THREE.Mesh(new THREE.PlaneGeometry(200,200),groundMat);terrain.rotation.x=-Math.PI/2;terrain.position.y=-.55;worldGroup.add(terrain);
// winding pale footpath
let path=add(new THREE.BoxGeometry(1,.025,1),pathMat,1,-.005,2);path.scale.set(8,1,1.3);path.rotation.y=-.27;
// tent and cabin
let tent=new THREE.Group();worldGroup.add(tent);let tentBody=add(new THREE.ConeGeometry(1.18,1.55,4),cream,-4,.56,0,tent);tentBody.rotation.y=Math.PI/4;tentBody.scale.set(1.08,1,1.1);let flap=box(-4,.22,1.0,dark,.72,.44,.03,tent);flap.rotation.x=-.3;let pole=cyl(-4,1.3,0,wood,.035,.035,1.8,tent);let cabin=new THREE.Group();cabin.name='cabin';worldGroup.add(cabin);box(-4,.62,0,wood,3.2,1.25,2.5,cabin);let cabinRoof=add(new THREE.ConeGeometry(2.35,.95,4),roof,-4,1.65,0,cabin);cabinRoof.rotation.y=Math.PI/4;cabinRoof.scale.set(1.2,1,1.05);box(-4,.43,1.27,dark,.72,.88,.08,cabin);box(-4.9,.8,1.28,blue,.58,.48,.06,cabin);box(-3.1,.8,1.28,blue,.58,.48,.06,cabin);
// solar array panel group
let solar=new THREE.Group();solar.name='solar';solar.position.set(-5.4,0,-3.6);worldGroup.add(solar);for(let i=0;i<5;i++){let p=new THREE.Group();solar.add(p);p.position.x=(i%3)*1.12;p.position.z=Math.floor(i/3)*1.12;let panel=box(0,.52,0,solarMat,1,.08,.72,p);panel.rotation.x=-.18;for(let j=-1;j<=1;j++){let line=box(j*.3,.565,0,mat(0x7796a1,.45),.018,.012,.67,p);line.rotation.x=-.18;}cyl(0,.22,0,dark,.045,.04,.5,p)}
// garden beds
