(()=>{
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const defaults={day:1,coins:45,produce:3,water:80,food:78,thirst:82,well:92,panels:1,battery:1,inverter:1,voltage:12,series:1,pump:0,wellUpgrade:0,house:0,garden:0,animals:0,seeded:0,harvest:0,dayProgress:0,rotation:0,zoom:1,sound:true,visited:[],lastDay:Date.now()};
let s={...defaults,...JSON.parse(localStorage.getItem('hearthwild-save')||'{}')};let activeTab='today',toastTimer,renderer,scene,camera,worldGroup;
const seasons=['SPRING','SUMMER','AUTUMN','WINTER'],season=()=>seasons[Math.floor((s.day-1)/18)%4],seasonIndex=()=>seasons.indexOf(season());
const cropData={Radishes:{seasons:[0,1,2],days:2,water:12,seed:4,price:12,icon:'◉',info:'Quick-growing and cool-season friendly. Radishes are ready in just a couple of days.'},Beans:{seasons:[1,2],days:3,water:18,seed:7,price:20,icon:'⌁',info:'Beans love warm soil and add nitrogen back to the garden. Give them a little room to climb.'},Kale:{seasons:[0,2,3],days:4,water:16,seed:6,price:18,icon:'❋',info:'A hardy leafy green that handles cool weather. Mulch helps protect roots through a light frost.'},Tomatoes:{seasons:[1],days:4,water:24,seed:9,price:26,icon:'●',info:'Tomatoes need warm nights, steady moisture, and lots of sun. Avoid wetting leaves to limit disease.'}};
function save(){localStorage.setItem('hearthwild-save',JSON.stringify(s))}
function showToast(t){let el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function seasonCrop(){return Object.keys(cropData).filter(k=>cropData[k].seasons.includes(seasonIndex()))}
function doAction(type,arg){switch(type){case'water':if(s.water<10)return showToast('Not enough water — haul some in or upgrade your collection.');s.water-=10;s.thirst=Math.min(100,s.thirst+25);s.well=Math.min(100,s.well+2);showToast('A good drink. You feel more like yourself.');break;case'eat':if(s.produce<1)return showToast('No harvest to eat yet. Try gathering wild greens.');s.produce--;s.food=Math.min(100,s.food+30);s.well=Math.min(100,s.well+3);showToast('A simple meal, grown by you.');break;case'gather':s.food=Math.min(100,s.food+13);s.produce++;showToast('Found wild berries and greens. Always identify plants first!');break;case'plant':if(s.seeded)return showToast('There is already a crop growing.');let c=arg||seasonCrop()[0],d=cropData[c];if(!d||!d.seasons.includes(seasonIndex()))return showToast(`${c} prefers a different season.`);if(s.coins<d.seed)return showToast('Not enough credits for those seeds.');if(s.water<d.water)return showToast('Not enough water to plant that crop. Haul in water first.');s.coins-=d.seed;s.water-=d.water;s.seeded={crop:c,progress:0,watered:true};s.garden=Math.max(s.garden,1);showToast(`${c} planted — keep it watered!`);break;case'waterCrop':if(!s.seeded)return;if(s.water<8)return showToast('You need 8 litres to water the garden.');s.water-=8;s.seeded.watered=true;showToast('Garden watered. A little goes a long way.');break;case'harvest':if(!s.seeded||s.seeded.progress<cropData[s.seeded.crop].days)return showToast('Not ready yet. Give it time and water.');s.produce+=2+(s.pump?1:0);s.harvest++;s.seeded=null;showToast('Harvest gathered! Two portions for your pantry.');break;case'haul':if(s.coins<15)return showToast('You need 15 credits for a water delivery.');s.coins-=15;s.water+=100;showToast('Water delivery arrived: +100 litres.');break;case'rest':s.well=Math.min(100,s.well+24);s.food=Math.max(0,s.food-5);s.thirst=Math.max(0,s.thirst-6);showToast('A quiet rest restores your wellbeing.');break;case'trade':if(s.produce<1)return showToast('No harvest to sell yet.');s.produce--;s.coins+=12;showToast('Produce sold at the local market. +12 credits');break;case'feed':if(s.produce<1)return showToast('You need one harvest to feed your chickens.');s.produce--;s.food=Math.min(100,s.food+15);s.coins+=7;showToast('Eggs and a meal! The hens are earning their keep.');break;case'buy':purchase(arg);return;case'next':nextDay();return;case'config':configSystem();return;case'explore':if(s.well<15)return showToast('Rest first; exploring while exhausted is risky.');s.coins+=12;s.water+=4;s.food=Math.max(0,s.food-7);s.well-=9;showToast('A short walk found a nearby market: +12 credits.');break;}update()}
const upgrades={panel:{name:'Solar panel',icon:'☼',desc:'More sunlight captured each day.',cost:40,cap:5,key:'panels',learn:'Solar panels are wired in series to raise voltage, or parallel to add current. Matching panel specs matters.'},battery:{name:'Battery bank',icon:'▰',desc:'Store extra energy for cloudy days.',cost:45,cap:5,key:'battery',learn:'Batteries store energy, not make it. Capacity (Wh) = voltage × amp-hours; avoid draining lead-acid below about 50%.'},inverter:{name:'Pure sine inverter',icon:'ϟ',desc:'Run more useful AC appliances.',cost:55,cap:4,key:'inverter',learn:'An inverter changes DC battery power to household AC. Size it for peak watts, and remember conversion losses.'},pump:{name:'Drip irrigation',icon:'⌁',desc:'Use less water, grow more food.',cost:50,cap:1,key:'pump',learn:'Drip irrigation delivers water at the roots and can use 30–50% less than overhead watering.'},wellUpgrade:{name:'Rain catchment',icon:'◉',desc:'Collect more from every rainfall.',cost:35,cap:3,key:'wellUpgrade',learn:'A 1 mm rain on 1 m² of roof yields about 1 litre before losses. Gutters and a covered tank make collection practical.'},house:{name:'Shelter upgrade',icon:'⌂',desc:'Trade canvas for a sturdier roof.',cost:60,cap:3,key:'house',learn:'Insulation reduces heating needs. Start with a dry, tight envelope, then add appropriately sized systems.'},garden:{name:'Garden beds',icon:'❋',desc:'Make room for another crop.',cost:35,cap:3,key:'garden',learn:'Rotate crop families and keep living roots in the soil when possible to support soil health.'},animals:{name:'A few hens',icon:'♧',desc:'Eggs, companionship, daily chores.',cost:75,cap:1,key:'animals',learn:'Chickens need secure night housing, clean water, feed, and daily care. They are a commitment, not a machine.'}};
function purchase(k){let u=upgrades[k];if(!u)return;let n=s[u.key],cost=u.cost+n*15;if(n>=u.cap)return showToast('You have reached the current upgrade limit.');if(s.coins<cost)return showToast(`You need ${cost} credits for this upgrade.`);if(k==='house'&&s.house===0&&s.panels<2)return showToast('Add one more panel before building a bigger shelter.');s.coins-=cost;s[u.key]++;if(k==='panel'&&s.panels===2)s.voltage=24;if(k==='panel'&&s.panels>=4)s.voltage=48;showToast(`${u.name} upgraded!`);s.visited.push(u.learn);update()}
function nextDay(){s.day++;s.dayProgress=0;s.food=Math.max(0,s.food-8);s.thirst=Math.max(0,s.thirst-12);s.well=Math.max(0,s.well-2);if(seasonIndex()===3)s.well=Math.max(0,s.well-2);if(s.animals)s.food=Math.min(100,s.food+5);if(s.seeded){if(s.seeded.watered){s.seeded.progress++;s.seeded.watered=false}else{s.seeded.progress=Math.max(0,s.seeded.progress-1);showToast('Your crop wilted a little without water.')}}if(Math.random()<(.25+s.wellUpgrade*.06)){s.water+=Math.round(8+s.wellUpgrade*8);showToast('Rain! Catchment added water to your tank.')}s.water=Math.min(250+s.wellUpgrade*100,s.water);if(s.day%3===0){s.coins+=5;showToast('A small homestead stipend: +5 credits.')}if(s.day%6===0){let w=['Clear','Breezy','Cloudy','Rain'];$('#weatherLabel').textContent=w[Math.floor(Math.random()*w.length)]}s.lastDay=Date.now();update()}
function update(){let labels={dayNumber:`DAY ${String(s.day).padStart(2,'0')}`,seasonLabel:season(),foodVal:Math.round(s.food),thirstVal:Math.round(s.thirst),wellVal:Math.round(s.well),coinVal:s.coins,produceVal:s.produce,waterVal:s.water,weatherShort:season()==='WINTER'?'Cold · 4°':season()==='SUMMER'?'Warm · 27°':'Mild · 18°'};Object.entries(labels).forEach(([id,v])=>{if($('#'+id))$('#'+id).textContent=v});[['foodMeter',s.food],['thirstMeter',s.thirst],['wellMeter',s.well]].forEach(([id,v])=>$('#'+id).style.width=Math.max(0,Math.min(100,v))+'%');$('#dayProgress').style.width=(s.dayProgress||22)+'%';$('#shelterLabel').lastChild.textContent=s.house>=3?'CABIN':s.house>=1?'SHELTER':'TENT';$('#captionText').textContent=s.house>=3?'A cabin, built one good decision at a time.':s.house?'A sturdier shelter, and room to dream.':'A quiet place to begin again.';$('#chapterLabel').textContent=s.house>=3?'CHAPTER THREE · ROOTED':'CHAPTER ONE · A PLACE TO LAND';$('#welcomeTitle').innerHTML=s.house>=3?'Rooted in the<br><em>wild.</em>':s.house?'Build a life<br><em>that fits.</em>':'Make this place<br><em>your own.</em>';if(activeTab==='today')renderToday();if(activeTab==='homestead')renderHomestead();if(activeTab==='fieldbook')renderNotes();save();if(worldGroup)updateScene()}
function renderToday(){let c=seasonCrop(),grow=s.seeded?`<div class="task"><div class="task-icon">${cropData[s.seeded.crop].icon}</div><div class="task-copy"><strong>${s.seeded.crop} · day ${s.seeded.progress}/${cropData[s.seeded.crop].days}</strong><small>${s.seeded.progress>=cropData[s.seeded.crop].days?'Ready to harvest!':s.seeded.watered?'Watered for today':'Needs 8 L of water'}</small></div><button class="task-action" data-action="${s.seeded.progress>=cropData[s.seeded.crop].days?'harvest':'waterCrop'}">${s.seeded.progress>=cropData[s.seeded.crop].days?'Harvest':s.seeded.watered?'Grow':'Water · 8 L'}</button></div>`:`<div class="task"><div class="task-icon">❋</div><div class="task-copy"><strong>Plant a seasonal crop</strong><small>${c.join(', ')} grow well right now</small></div><button class="task-action" data-action="plant" data-arg="${c[0]}">Plant · ${cropData[c[0]].seed} cr</button></div>`;$('#content').innerHTML=`<div class="section-head"><span class="section-title">A good day starts small</span><span class="section-sub">${season().toLowerCase()} day ${s.day}</span></div><div class="weather-note"><span class="weather-ico">${season()==='WINTER'?'❄':'☀'}</span><div><strong>${season()} on the homestead</strong><p>${season()==='WINTER'?'Protect your water stores from freezing; kale can handle the chill.':season()==='SUMMER'?'Long sunny days are great for solar and warm-season crops. Water early to limit evaporation.':'A good time to plant cool-season crops and watch the forecast.'}</p></div></div><div class="section-head"><span class="section-title">Today’s little to-dos</span><span class="section-sub">one step at a time</span></div><div class="task-list"><div class="task"><div class="task-icon">◌</div><div class="task-copy"><strong>Drink some water</strong><small>${s.water} L in storage · stay ahead of thirst</small></div><button class="task-action" data-action="water">Drink</button></div><div class="task"><div class="task-icon">⌁</div><div class="task-copy"><strong>Make yourself a meal</strong><small>${s.produce} harvest portions in your pantry</small></div><button class="task-action" data-action="eat" ${s.produce<1?'disabled':''}>Cook</button></div>${grow}<div class="task"><div class="task-icon">☾</div><div class="task-copy"><strong>Take a breather</strong><small>Rest restores wellbeing, but takes a little daylight</small></div><button class="task-action" data-action="rest">Rest</button></div></div><div class="section-head gap"><span class="section-title">Your 12 V starter system</span><span class="section-sub">${s.voltage} V · DC</span></div><div class="energy-card"><div class="energy-head"><div class="energy-title"><i>ϟ</i> OFF-GRID POWER</div><span>${s.panels} panel${s.panels!==1?'s':''} · ${s.battery} battery</span></div><div class="energy-stats"><div class="energy-stat"><b>${s.panels*100} W</b><small>panel output</small></div><div class="energy-stat"><b>${s.voltage} V</b><small>system voltage</small></div><div class="energy-stat"><b>${s.battery*600} Wh</b><small>stored energy</small></div></div><div class="energy-bar"><span style="width:${Math.min(100,30+s.panels*12)}%"></span></div><div class="energy-foot"><span>Sunny day estimate</span><span>${s.panels*350} Wh/day ☀</span></div></div><div class="footer-tip">✦ &nbsp;${s.voltage===12?'At 12 V, a 1,000 W load draws ~83 A — short, thick cables matter.':'Higher voltage means less current for the same power; your wiring can be more efficient.'}</div><div class="task" style="margin-top:9px"><div class="task-icon">⌂</div><div class="task-copy"><strong>Take a little walk</strong><small>Find supplies and a few credits nearby</small></div><button class="task-action" data-action="explore">Explore</button></div><div class="task" style="margin-top:7px"><div class="task-icon">◷</div><div class="task-copy"><strong>Turn in for the night</strong><small>Tomorrow brings another chance</small></div><button class="task-action" data-action="next">End day →</button></div>`}
function renderHomestead(){let keys=Object.keys(upgrades);$('#content').innerHTML=`<div class="section-head"><span class="section-title">Build your off-grid life</span><span class="section-sub">${s.coins} credits available</span></div><div class="system-card"><div class="system-top"><strong>⚡ Power system</strong><span class="system-pill">${s.voltage} V ${s.voltage===12?'starter':'system'}</span></div><div class="system-grid"><div><b>${s.panels} × 100 W</b><small>solar panels</small></div><div><b>${s.battery} × 600 Wh</b><small>battery bank</small></div><div><b>${s.inverter*300} W</b><small>inverter</small></div></div><button class="config-btn" data-action="config">Configure series / parallel ⟶</button></div><div class="upgrade-detail"><b>Power in plain language</b> · Series wiring adds voltage; parallel wiring adds current. Keep panel ratings compatible and use proper fuses. Your 12 V starter can grow to 24 V, then 48 V.</div><div class="section-head"><span class="section-title">Homestead upgrades</span><span class="section-sub">buy with credits</span></div><div class="upgrade-grid">${keys.map(k=>{let u=upgrades[k],n=s[u.key],cost=u.cost+n*15;return `<div class="upgrade-card"><div class="upgrade-icon">${u.icon}</div><h3>${u.name}</h3><p>${u.desc}${n?` · lvl ${n}`:''}</p><button class="upgrade-btn" data-action="buy" data-arg="${k}" ${n>=u.cap||s.coins<cost?'disabled':''}>${n>=u.cap?'Max level':`Upgrade · ${cost} cr`}</button></div>`}).join('')}</div><div class="section-head gap"><span class="section-title">A little more water</span><span class="section-sub">${s.water} L stored</span></div><div class="task"><div class="task-icon">◉</div><div class="task-copy"><strong>Haul in a 100 L delivery</strong><small>Reliable, costs 15 credits · rain is free but uncertain</small></div><button class="task-action" data-action="haul" ${s.coins<15?'disabled':''}>Order · 15 cr</button></div><div class="footer-tip">Water budget: garden crops need roughly 12–24 L through a short growing cycle; usage varies with weather and soil.</div>`}
function renderNotes(){let cards=[['Electricity · your 12 V start','⟐',`Your system starts at 12 V with ${s.panels} × 100 W panels. A 12 V, 600 Wh battery stores about 50 Ah (600 ÷ 12), before losses. A real setup needs a charge controller, fuses, correctly sized wire, and safe installation.`],['Series or parallel?','⌁','Wire panels in <b>series</b> to add their voltages while current stays similar. Wire in <b>parallel</b> to keep voltage the same while currents add. Never exceed your charge controller’s voltage limit. Batteries must be matched and connected safely.'],['Water · every drop counts','◉','Plants need water to move nutrients and cool their leaves. A simple drip line puts water near roots. Mulch reduces evaporation. Rain capture depends on roof area and rainfall: litres ≈ rain (mm) × roof area (m²) × collection efficiency.'],['Seasonal growing','❋',`It is ${season().toLowerCase()}. ${seasonCrop().join(', ')} can grow now. Cool-weather crops like kale tolerate frost; tomatoes need warm nights. Local frost dates, sunlight, and your growing zone matter.`],['Living with animals','♧',s.animals?'Your hens need clean water, secure housing, balanced feed, and daily checks. Egg production changes with daylight and season.':'A few hens can provide eggs, but they need secure night housing, fresh water, balanced feed, and daily care. Plan the daily chores before you bring animals home.'],['Shelter & energy','⌂',`Your current shelter: <b>${s.house>=3?'cabin':s.house?'upgraded shelter':'tent'}</b>. Reduce energy needs first with shade, insulation, efficient appliances, and good habits. An inverter converts battery DC to household AC, but loses some energy as heat.`]];$('#content').innerHTML=`<div class="section-head"><span class="section-title">What the homestead is teaching</span><span class="section-sub">real-world notes</span></div>${cards.map(([h,i,p])=>`<div class="note-card"><div class="note-card-head"><span class="note-ico">${i}</span><strong>${h}</strong></div><p>${p}</p></div>`).join('')}<div class="upgrade-detail">These are simplified learning models, not installation instructions. Real electrical systems can cause fire or injury: consult local codes and a qualified professional.</div>`}
function configSystem(){let html=`<p>Panel strings change the voltage and current delivered to a controller. Use only a configuration your equipment supports.</p><div class="modal-callout"><b>Your homestead:</b> ${s.panels} panels · ${s.voltage} V target · ${s.battery} battery bank<br>Series: <b>${s.series}</b> panel${s.series!==1?'s':''} per string · parallel strings: <b>${Math.max(1,Math.floor(s.panels/s.series))}</b></div><p><strong>Choose panels in series per string:</strong></p><div>${[1,2,4].filter(n=>n<=Math.max(1,s.panels)).map(n=>`<button class="task-action config-choice" data-series="${n}" style="margin:0 6px 6px 0" ${n===s.series?'disabled':''}>${n} in series${n===s.series?' · selected':''}</button>`).join('')}</div><p>More series panels raise array voltage; more parallel strings increase current. The controller must be rated for array voltage and current.</p><div class="modal-callout">${s.panels>=4?'48 V is available with four panels in series.':s.panels>=2?'24 V is available with two panels in series.':'Add panels before increasing your system voltage.'}</div>`;openModal('A tidy little power system',html);$$('.config-choice').forEach(b=>b.onclick=()=>{s.series=+b.dataset.series;s.voltage=s.series>=4?48:s.series>=2?24:12;showToast(`${s.series} panels in series · ${s.voltage} V`);closeModal();update()})}
