function doAction(type,arg){switch(type){
case'water':if(s.water<10)return showToast('Not enough water — haul some in or upgrade your collection.');
s.water-=10;
s.thirst=Math.min(100,s.thirst+25);
s.well=Math.min(100,s.well+2);
showToast('A good drink. You feel more like yourself.');
break;


case'eat':if(s.produce<1)return showToast('No harvest to eat yet. Try gathering wild greens.');
s.produce--;
s.food=Math.min(100,s.food+30);
s.well=Math.min(100,s.well+3);
showToast('A simple meal, grown by you.');
break;


case'gather':s.food=Math.min(100,s.food+13);
s.produce++;
showToast('Found wild berries and greens. Always identify plants first!');
break;


case'plant':if(s.seeded)return showToast('There is already a crop growing.');
let c=arg||seasonCrop()[0],d=cropData[c];
if(!d||!d.seasons.includes(seasonIndex()))return showToast(`${c} prefers a different season.`);
if(s.coins<d.seed)return showToast('Not enough credits for those seeds.');
if(s.water<d.water)return showToast('Not enough water to plant that crop. Haul in water first.');
s.coins-=d.seed;
s.water-=d.water;
s.seeded={crop:c,progress:0,watered:true};
s.garden=Math.max(s.garden,1);
showToast(`${c} planted — keep it watered!`);
break;


case'waterCrop':if(!s.seeded)return;
if(s.water<8)return showToast('You need 8 litres to water the garden.');
s.water-=8;
s.seeded.watered=true;
showToast('Garden watered. A little goes a long way.');
break;


case'harvest':if(!s.seeded||s.seeded.progress<cropData[s.seeded.crop].days)return showToast('Not ready yet. Give it time and water.');
s.produce+=2+(s.pump?1:0);
s.harvest++;
s.seeded=null;
showToast('Harvest gathered! Two portions for your pantry.');
break;


case'haul':if(s.coins<15)return showToast('You need 15 credits for a water delivery.');
s.coins-=15;
s.water+=100;
