break;


case'rest':s.well=Math.min(100,s.well+24);
s.food=Math.max(0,s.food-5);
s.thirst=Math.max(0,s.thirst-6);
showToast('A quiet rest restores your wellbeing.');
break;


case'trade':if(s.produce<1)return showToast('No harvest to sell yet.');
s.produce--;
s.coins+=12;
showToast('Produce sold at the local market. +12 credits');
break;


case'feed':if(s.produce<1)return showToast('You need one harvest to feed your chickens.');
s.produce--;
s.food=Math.min(100,s.food+15);
s.coins+=7;
showToast('Eggs and a meal! The hens are earning their keep.');
break;


case'buy':purchase(arg);
return;

case'next':nextDay();
return;

case'config':configSystem();
return;

case'explore':if(s.well<15)return showToast('Rest first;
 exploring while exhausted is risky.');
s.coins+=12;
s.water+=4;
s.food=Math.max(0,s.food-7);
s.well-=9;
showToast('A short walk found a nearby market: +12 credits.');
break;

}update()}

