1: (()=>{
2: const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
3: const defaults={day:1,coins:45,produce:3,water:80,food:78,thirst:82,well:92,panels:1,battery:1,inverter:1,voltage:12,series:1,pump:0,wellUpgrade:0,house:0,garden:0,animals:0,seeded:0,harvest:0,dayProgress:0,rotation:0,zoom:1,sound:true,visited:[],lastDay:Date.now()};
4: let s={...defaults,...JSON.parse(localStorage.getItem('hearthwild-save')||'{}')};let activeTab='today',toastTimer,renderer,scene,camera,worldGroup;
5: const seasons=['SPRING','SUMMER','AUTUMN','WINTER'],season=()=>seasons[Math.floor((s.day-1)/18)%4],seasonIndex=()=>seasons.indexOf(season());
6: const cropData={Radishes:{seasons:[0,1,2],days:2,water:12,seed:4,price:12,icon:'◉',info:'Quick-growing and cool-season friendly. Radishes are ready in just a couple of days.'},Beans:{seasons:[1,2],days:3,water:18,seed:7,price:20,icon:'⌁',info:'Beans love warm soil and add nitrogen back to the garden. Give them a little room to climb.'},Kale:{seasons:[0,2,3],days:4,water:16,seed:6,price:18,icon:'❋',info:'A hardy leafy green that handles cool weather. Mulch helps protect roots through a light frost.'},Tomatoes:{seasons:[1],days:4,water:24,seed:9,price:26,icon:'●',info:'Tomatoes need warm nights, steady moisture, and lots of sun. Avoid wetting leaves to limit disease.'}};
7: function save(){localStorage.setItem('hearthwild-save',JSON.stringify(s))}
